est:"10M notifications/day avg ≈ 115/s; campaigns spike to 50k/s for a few minutes → queues absorb bursts. Status rows: 10M/day × 200 B ≈ 2 GB/day.",
ent:"<b>Notification</b>(id, user_id, channel, template_id, payload, priority, status, idempotency_key), <b>Preference</b>(user_id, channel, enabled, quiet_hours), <b>Template</b>, <b>DeviceToken</b>.",
api:["POST /v1/notifications {user_id, template, vars, channels?, priority, idempotency_key, send_at?} → 202 {id}","GET  /v1/notifications/{id} → status","PUT  /v1/users/{id}/preferences"],
dia:{w:760,h:290,n:[["c",70,145,"Calling services","orders · auth · marketing","client"],["api",230,145,"Notification API","validate · dedupe","svc"],["pref",230,40,"Prefs + templates","","db"],["qh",420,70,"High-priority queue","OTP","queue"],["ql",420,220,"Bulk queue","marketing","queue"],["wp",590,40,"Push workers","FCM / APNs","svc"],["ws",590,145,"SMS workers","Twilio","svc"],["we",590,250,"Email workers","SES","svc"],["log",720,145,"Status log","","db"]],e:[["c","api"],["api","pref"],["api","qh"],["api","ql"],["qh","wp"],["qh","ws"],["ql","we"],["ql","wp","",1],["ws","log","",1]],bw:124},
flow:"The API only validates and enqueues; channel workers talk to providers and record status.",
deep:[["Why queues per channel and priority","Providers have different speeds and limits; one slow email provider must not delay OTPs. Separate high/low priority queues (or Kafka topics) with dedicated worker pools."],["Dedupe and idempotency","Callers pass an idempotency_key; the API stores it with a unique index. Workers record (notification_id, channel) as sent before acking; on redelivery they skip."],["Retries","Exponential backoff with jitter for transient provider errors; switch to a backup provider after N failures; dead-letter queue for permanent failures (invalid number)."],["Preferences and quiet hours","Check preferences at enqueue and again at send. Quiet-hour messages go to a delay queue or scheduler."],["Rate limits","Per-user caps (no more than N marketing pushes/day) and per-provider throughput limits via token buckets in workers."]],
