dia:{w:760,h:290,n:[["a",60,70,"Alice","","client"],["b",60,220,"Bob","","client"],["w1",220,70,"WS gateway 1","","edge"],["w2",220,220,"WS gateway 2","","edge"],["chat",420,145,"Chat service","order · persist · fan-out","svc"],["sess",420,40,"Session registry","Redis: user → gateway","cache"],["msg",640,145,"Message store","Cassandra (chat_id, msg_id)","db"],["q",640,250,"Push service","APNs / FCM for offline","ext"]],e:[["a","w1","",0,1],["b","w2","",0,1],["w1","chat"],["chat","sess","where is Bob?"],["chat","w2","deliver"],["chat","msg","persist"],["chat","q","offline",1]],bw:130},
