dia:{w:760,h:290,n:[["c",60,145,"Clients","","client"],["ps",230,60,"Post service","","svc"],["fs",230,230,"Feed service","","svc"],["pdb",430,30,"Posts DB","","db"],["k",430,120,"Kafka","post.created","queue"],["fo",600,120,"Fan-out workers","skip celebrities","svc"],["tl",600,230,"Timeline cache","Redis lists","cache"],["g",720,30,"Follow graph","","db"]],e:[["c","ps","POST"],["c","fs","GET feed"],["ps","pdb"],["ps","k"],["k","fo"],["fo","g","followers",1],["fo","tl","push id"],["fs","tl","read"],["fs","pdb","hydrate + celeb posts",1]],bw:124},
