dia:{w:760,h:250,n:[["t",70,125,"Team services","","client"],["gw",270,125,"LLM gateway","auth · route · limit","edge"],["rl",270,30,"Redis","limits + budgets","cache"],["p1",510,50,"Provider A","","ext"],["p2",510,125,"Provider B","fallback","ext"],["self",510,200,"Self-hosted","vLLM","ext"],["log",700,125,"Logs + cost","traces · dashboards","db"]],e:[["t","gw"],["gw","rl"],["gw","p1"],["gw","p2","on error",1],["gw","self"],["gw","log","async",1]],bw:126},
